"use client";
import MarketplaceWorkspace from "../../../components/MarketplaceWorkspace";
export default function NewProductPage(){return <MarketplaceWorkspace title="Add a product" description="Product form scaffold. The listing will not be saved until authenticated product APIs, image storage, category validation and approval workflow are implemented." nav={[{label:"Overview",href:"/marketplace/vendors"},{label:"Products",href:"/marketplace/vendors/products",active:true}]}><form onSubmit={e=>e.preventDefault()} className="mx-auto max-w-4xl rounded-3xl border border-[#f0e3dc] bg-white p-5 sm:p-8"><div className="grid gap-4 sm:grid-cols-2">{[{label:"Product name *",type:"text"},{label:"SKU *",type:"text"},{label:"Brand",type:"text"},{label:"Category *",type:"text"},{label:"Selling price (PKR) *",type:"number"},{label:"Compare-at price (PKR)",type:"number"},{label:"Stock quantity *",type:"number"},{label:"Weight (kg)",type:"number"},{label:"Package length (cm)",type:"number"},{label:"Package width (cm)",type:"number"},{label:"Package height (cm)",type:"number"}].map(f=><label key={f.label}><span className="mp-label">{f.label}</span><input className="mp-input" type={f.type} min={f.type==="number"?0:undefined} disabled required={f.label.includes("*")} placeholder="Enabled after backend setup"/></label>)}<label className="sm:col-span-2"><span className="mp-label">Product photos</span><input className="mp-input" type="file" accept="image/*" multiple disabled/><small className="mt-1 block text-xs text-[#92847d]">Image storage is not configured.</small></label><label className="sm:col-span-2"><span className="mp-label">Description and specifications</span><textarea className="mp-input min-h-28" disabled placeholder="Product description, specifications, variant and policy fields will be connected later."/></label></div><div className="mt-6 rounded-xl bg-[#fff0e8] p-4 text-sm leading-6 text-[#9b4c3a]">All fields are intentionally disabled in this frontend-only scaffold. No product is saved or published.</div><button className="mp-primary mt-5 w-full opacity-60" type="button" disabled>Save draft · backend pending</button></form></MarketplaceWorkspace>}
